    faq_a_bag_examples_list: "Tas baru dilengkapi contoh yang bisa diubah atau dihapus seperti hal lainnya: Rumah (belanja, resep, menu minggu ini), Keluarga (momen kecil, daftar pesta ulang tahun, kegiatan dan kursus), Ide (ide akhir pekan, ide hadiah menurut seberapa dekat orangnya, dan mau diapakan uang yang kamu tabung) dan Perjalanan (tempat yang ingin kamu kunjungi, barang bawaan perjalanan, bawaan ke hotel, dan daftar terbang ke luar negeri). Tas yang sudah ada mendapat contoh terbaru satu kali, ke dalam kantong-kantongnya sendiri.",
    faq_q_bag_examples_list: "Contoh apa saja yang ada di Tas Saya?",
    faq_a_nm_me1_guide: "Me – karaktermu di New Me, dalam wujud pertamanya (Me1). Pertama kali, tepat setelah bergabung, sebuah portal cahaya terbuka dengan kilauan di sekelilingnya dan Me terbang keluar darinya, menjelaskan dalam beberapa ketukan apa yang menanti, lalu menemani di samping setiap pertanyaan: saat makanan dipilih, ia menulis bersamamu di bukunya, dan ketukan pada tipsnya menampilkan tips lain. Di akhir, Me merayakan bersamamu dan mengajakmu tur singkat – dan saat tur selesai, ia masih punya satu momen kecil lagi bersamamu. Kalau kamu keluar di tengah jalan – saat pertanyaan atau tur – lain kali Me senang melihatmu dan bertanya apakah mau melanjutkan dari tempat yang sama. \"Lewati\" di bagian atas melewati pembukaan.",
