    nm_m1_tip_ai: "Makanan yang tidak ada di daftar? Nanti, di \"Ganti\", kamu bisa menuliskannya dengan kata-katamu sendiri – dan AI akan menghitungnya. Sekarang, ayo kita pilih bersama mau makan apa setiap hari – dan tentu saja kamu selalu bisa menggantinya ✨",
    nm_m1_tip_love: "Makanan apa pun tak masalah – kalau kamu suka, ia tetap ada di menu 💛",
    nm_m1_tip_rice: "Nasi itu favoritku: ia jadi dasarnya, dengan sedikit dari segalanya di sekelilingnya 🍚",
    faq_a_shop_basics: "Saat Daftar Belanja benar-benar kosong – misalnya di awal sekali – muncul daftar dasar untuk memulai: susu, roti, telur, dan lainnya. Ketukan pada sebuah barang menambahkannya ke daftar, dan “Tambahkan semua” menambahkan semuanya sekaligus. Begitu ada sesuatu di daftar, daftar dasar ini menghilang.",
    faq_q_shop_basics: "Apa itu daftar dasar di Daftar Belanja yang kosong?",
    shop_basics_all: "Tambahkan semua",
    shop_basics_items: "susu|roti|telur|tomat|timun|keju|beras|pasta|minyak zaitun|apel|pisang|tisu toilet",
    shop_basics_title: "Daftar dasar untuk memulai",
