    room_genie_again_no: "Tidak sekarang",
    room_genie_again_no_msg: "Kalau begitu, saatnya mencapai target yang sudah kamu tetapkan. Saat kamu sampai di target berikutnya – ada sesuatu yang menunggumu di sana ✨",
    room_genie_again_q: "Kembali lagi? ✨ Apa ada hal lain dalam hidupmu yang ingin kamu ubah?",
    room_genie_again_yes: "Ya",
    room_genie_bye: "Sampai jumpa",
    room_genie_rest: "Roh hutan sedang beristirahat – kembali lagi besok, ya ✨",
    faq_a_shop_holidays: "Di Daftar Belanja, ketuk hadiah: hari raya di negara Anda (yang dipilih di Pengaturan) muncul berurutan, lengkap dengan tanggalnya – dihitung otomatis setiap tahun. Ketuk sebuah hari raya untuk melihat daftar siap pakai berisi apa yang biasa dibeli orang untuk hari itu; semuanya sudah terpilih (kecuali yang sudah ada di daftar Anda), hapus centang pada yang tidak perlu, lalu ketuk “Tambahkan ke daftar”. Dua minggu sebelum hari raya, sebuah kartu kecil muncul di bagian atas daftar; ✕ menyembunyikannya sampai hari raya berikutnya.",
    faq_q_shop_holidays: "Bagaimana cara kerja “Apa yang dibeli untuk hari raya”?",
    shop_hol_add: "Tambahkan ke daftar ({n})",
    shop_hol_added: "Ditambahkan ke daftar: {n}",
    shop_hol_btn: "Apa yang dibeli untuk hari raya",
    shop_hol_items_title: "{holiday} – beli apa?",
    shop_hol_not_now: "Nanti saja",
    faq_a_shop_delivery: "Di Daftar Belanja, ketuk truk: pilih apa saja isi pesanan (semuanya sudah terpilih), kapan tibanya – hari ini, besok, atau hari lain – dan pada jam berapa (pagi, siang, sore, atau “Lainnya…” untuk jam pilihan sendiri). Barang-barang itu pindah ke kartu “Dalam perjalanan” di bagian atas daftar, lengkap dengan hari dan jamnya. Saat harinya tiba, “Pesanan sudah tiba?” muncul di Hariku (dan kartunya punya tombol “Sudah tiba?”). Jika semuanya tiba, barang-barang pindah ke “Beli lagi”. Jika ada yang kurang, ketuk barang yang tidak datang dan barang itu langsung kembali ke daftar.",
    faq_a_shop_departments: "Daftar ini menyusun dirinya sendiri sesuai bagian di supermarket – buah & sayur, roti, susu & telur, daging & ikan, bahan pokok, makanan beku, minuman, camilan, kebersihan, perawatan diri, bayi, dan hewan peliharaan – jadi Anda bisa menyusuri lorong secara berurutan. Bagian dikenali dari nama barang. Jika sebuah barang masuk ke tempat yang salah, ketuk barang itu dan pilih bagiannya, atau “Lainnya…” untuk menulis bagian sendiri.",
    faq_a_shop_share_qty: "Bisa. Di samping setiap barang, + menambah satu (×2, ×3…) dan − mengurangi satu. Tombol bagikan di bagian atas Daftar Belanja mengirim seluruh daftar, tersusun rapi per bagian, lewat WhatsApp, email, atau sebagai salinan.",
    faq_a_shop_two_buttons: "Keduanya berarti “sudah dibeli”. ✕ untuk barang yang Anda beli sekali saja – barang itu keluar dari daftar (dan menunggu di 🗑️ arsip kalau ternyata salah). ↺ untuk barang yang Anda beli berulang kali – barang itu keluar dari daftar dan menunggu di “Beli lagi”: tombol kecil ↺ di sebelah tempat sampah di bagian bawah daftar membukanya, dan satu ketukan di sana mengembalikan barang ke daftar. Lewat “Edit” di dalamnya, Anda bisa mengeluarkan barang dari sana. Saat Anda menambahkan barang, barang yang pernah Anda beli muncul sebagai saran, dan jika barang itu sudah ada di daftar, ia hanya menjadi ×2, bukan baris kedua.",
