    nm_demo_title: "Begini cara mengganti makanan",
    faq_a_new_me_challenge_journal: "Saat sebuah tantangan berakhir – besar, mini, atau tantangan minggu ini – di perayaannya ada tombol 📝 Bagaimana rasanya? yang membuka halaman di jurnal tantangan: bagaimana perasaanmu (lima wajah), apa yang membantu, apa yang berat, dan apa yang saya bawa dari sini – tidak ada yang wajib, dan bisa juga diisi nanti. Jurnal ini adalah sebuah berlian di tas ajaib: setiap tantangan yang selesai beserta tanggal dan apa yang ditulis, yang terbaru paling atas – ketuk salah satunya untuk membaca, mengedit, atau membagikannya (hanya isi halaman itu yang dibagikan). Tantangan yang selesai juga mendapat medali di pencapaian, di bawah “Tantangan yang saya selesaikan”. Jurnal tantangan terpisah dari buku harian.",
