    nm_chj_title: "Jurnal tantangan",
    nm_chj_write: "Tulis bagaimana jalannya",
    nm_swap_time: "Waktu",
    faq_a_ai_reminder_in_text: "Bisa – tulis saja bersama tugasnya, misalnya “besok jam 17:00 ambil paket, dengan pengingat satu jam sebelumnya”. Pengingat disimpan di tugas itu sendiri: satu jam sebelumnya, setengah jam, sehari sebelumnya, dan seterusnya, dan “ingatkan saya” tanpa waktu berarti 10 menit sebelumnya. Pengingat yang ditulis dalam teks lebih diutamakan daripada kolom pengingat di jendela yang sama.",
    faq_q_ai_reminder_in_text: "Bisakah saya meminta pengingat ke asisten AI dalam permintaan yang sama?",
    myday_meals_all_done: "Semua makan hari ini sudah dicentang 🍽️",
    nm_tour_week_text: "Tantangan kecil untuk seminggu. ✓ setiap hari – kunci di akhir.",
    books_home_chip: "{title} · hlm. {page}",
    books_home_of: "dari {total}",
    books_home_off_toast: "Buku dilepas dari layar utama",
    books_home_on_toast: "Buku ada di layar utama 📖",
    books_home_pin: "Di layar utama",
    books_home_q: "Aku sedang di halaman berapa?",
    books_home_save: "Simpan",
    faq_a_books_home_chip: "Bisa. Di Pojok Baca, pada kartu buku yang sedang dibaca, ketuk 📌 Di layar utama. Tombol kecil berisi buku dan halaman akan muncul di bawah sapaan di layar utama – ketuk, ketik nomor halaman baru dan simpan, lalu kemajuannya tercatat (di Pojok Baca juga). Mengetuk 📌 lagi akan melepaskannya. Beberapa buku bisa ada di sana bersamaan – satu tombol untuk masing-masing – dan sama di semua perangkat.",
    faq_a_new_me_week_challenge: "Tantangan kecil selama satu minggu, yang kamu pilih sendiri. Di lorong ada kartu besar: “Apa yang ingin kamu kerjakan minggu ini?” – ketuk, pilih bidang (dengan diri sendiri, dengan orang lain, belajar dan bertumbuh, ketenangan, langkah kecil yang berani, rumah dan rutinitas) dan satu tantangan, lalu tentukan kapan dimulai. Tantangan yang sama juga ada di layar tantangan, di bawah 🌱 Pengembangan diri. Setiap hari beri ✓ pada kartu (satu hari bebas dalam seminggu), dan setiap minggu yang selesai membawa kunci baru untuk dunia rahasia. “Baca 2 halaman sehari” otomatis tercentang dari halaman yang dicatat di Pojok Baca. Saat minggunya berakhir, 📌 Jadikan tugas harian menambahkannya ke Rutinitas Saya pada jam yang kamu pilih, dengan ✓ setiap hari. Hanya satu tantangan minggu ini yang berjalan pada satu waktu; tantangan besar dan mini tetap berjalan bersamanya.",
    faq_a_room_genie: "Di teras menghadap laut, mengetuk lampu Aladin memunculkan roh hutan – dan sebuah percakapan dimulai: apa harapanmu (apa yang ingin kamu ubah dalam hidup), bagaimana rasanya saat terwujud, apa yang sulit di perjalanan, dan bagaimana keadaan saat ini bisa diubah menjadi sesuatu yang baik. Lalu kira-kira berapa lama waktunya, satu langkah kecil pertama dan dua langkah lagi, serta sebuah “jika… maka…” untuk saat terasa sulit. Di akhir, seluruh harapan muncul selangkah demi selangkah, dan bisa dijadikan target di Target Saya (langkah-langkahnya menjadi tonggak di jalan, dengan tanggal sesuai waktu yang dipilih; semuanya bisa diubah di sana) atau disimpan di buku harian – lalu roh berpamitan. Tidak ada yang tersimpan kecuali salah satunya dipilih. Mulai kunjungan kedua, roh lebih dulu bertanya apakah kamu ingin mengubah hal lain dalam hidupmu: ya – percakapan yang sama; tidak sekarang – pengingat untuk mencapai target yang sudah ditetapkan. Roh keluar sekali sehari: setelah sebuah harapan disimpan (atau setelah “Tidak sekarang”), ia beristirahat sampai besok. Pertanyaannya mengikuti cara yang terkenal untuk mengubah harapan menjadi rencana: harapan, hasil, hambatan, dan rencana.",
    faq_q_books_home_chip: "Bisakah aku melihat buku dan halamannya di layar utama?",
    faq_q_new_me_week_challenge: "Apa itu tantangan minggu ini?",
