    nm_me_on_screen: "Di layar",
    faq_a_new_me_game: "Di New Me, tombol permainan selalu ada di tempat yang sama – di lorong, di kamar rahasia, dan di mana pun di hutan; hanya lukisan di tengah yang berganti. Di atas: hari ke berapa dalam perjalanan, kunci, rentetan, dan energi hari ini (seberapa banyak yang sudah dimakan dari rencana), dan di bawahnya misi berikutnya – makanan berikutnya pada waktunya (ketuk untuk membukanya, lengkap dengan ✓ Sudah makan). Di satu sisi: sepanjang hari, tantangan, dan perjalanan saya, dan di sebelahnya tantangan minggu ini – 7 harinya dan ✓ untuk hari ini. Di bawah: tas ajaib (seluruh New Me – peta dunia, perjalanan saya, daftar belanja, pencapaian, jurnal tantangan, ukuran tubuh, foto progres, kalender bulanan, tabel harian, pengingat, PDF menu, dan pengaturan; terbuka sebagai layar tersendiri). Peta dunia, hal pertama di dalam tas, menampilkan setiap tempat di hutan – ketuk sebuah tempat untuk pergi ke sana; tempat yang terkunci menunjukkan berapa kunci yang dibutuhkan. Me adalah karaktermu di jalan setapak di hutan: ia mulai sebagai Me1, setelah beberapa tantangan (4 kunci) tumbuh menjadi Me2, dan menjelang akhir (9 kunci) menjadi Me3 – dengan perubahan penampilan yang bisa kamu saksikan. Ketuk Me untuk melihat setiap tahap – karakter mana pun yang sudah dicapai bisa dipilih lagi, sehingga karakter sebelumnya bisa kembali. Me melayang – seret dengan jari atau mouse, dan pintu masuk yang disentuhnya terbuka (pintu yang terkunci menunjukkan berapa kunci yang kurang). Me juga ikut masuk ke setiap kamar dan tempat, dan melayang di mana pun kamu meninggalkannya: seret ke mana saja, dan seret cincin bercahaya di bawahnya untuk memutarnya sepenuhnya; ia menghadap ke arah geraknya (di komputer: tombol panah menggerakkannya, Q dan E memutarnya). Di lorong, 🏠 kecil di bawah bilah atas akan kembali ke layar utama; di setiap kamar dan tempat, tombol di sudut yang sama akan kembali ke lorong.",
    faq_q_new_me_game: "Bagaimana cara kerja tombol permainan, peta dunia, dan Me?",
