    faq_a_new_me_menu_build: "Pertama, kuesioner menanyakan waktu makan apa saja dan jam berapa (2 kali makan + camilan, 2 kali makan + makan malam ringan, atau keduanya), serta apakah ada sesuatu di malam hari – untuk dimakan atau diminum, apa, dan jam berapa. Dengan “2 kali makan + camilan”, waktu makannya adalah makan siang (11:30) dan makan malam (19:00), dengan camilan pukul 16:00. Lalu semua pilihan untuk waktu makan itu muncul. Pilih hingga 2 favorit untuk setiap waktu makan – menu menampilkan “ini atau itu”. Di beberapa pilihan (pita & olesan, cornflakes & susu, sesuatu yang ringan) pilih hingga 3 hal yang disukai, masing-masing dengan porsinya sendiri, dan menu menampilkan “ini atau itu atau itu”; kalorinya mengikuti yang dipilih. Kopi dan minuman juga begitu. Setiap pilihan diseimbangkan, jadi total harian tepat 1.300 atau 1.500. Untuk mengubahnya kapan saja: ⚙️ Pengaturan → 🍽️ Susun menumu, atau “Pilih hingga 3 yang disukai” di kartu waktu makan.",
