    faq_a_myday_water_toggle: "Bisa. Gelas air di 'Hariku' (dengan + untuk satu gelas lagi) tampil secara default. Untuk menyembunyikannya, matikan \"Tampilkan air di 'Hariku'\" di Pengaturan > Personalisasi & Kalender. Tidak ada yang dihapus – Pelacakan Air tetap berjalan, dan menyalakannya lagi mengembalikan gelasnya.",
    faq_q_myday_water_toggle: "Bisakah air di 'Hariku' disembunyikan?",
    myday_water_toggle_label: "Tampilkan air di 'Hariku'",
    faq_a_routine_newme_sync: "Dengan New Me, ⚙️ di Rutinitas Saya punya sakelar 'Sinkronkan dengan New Me'. Saat menyala (bawaan), makanan New Me hari ini muncul di Hariku dan di Rutinitas Saya – menggantikan makanan rutinitas yang disembunyikan. Saat mati, makanan New Me keluar dari keduanya dan rutinitas kembali persis seperti semula. Tidak ada yang dihapus – menyalakannya lagi mengembalikan semuanya dan menanyakan makanan rutinitas mana yang disembunyikan.",
