    theme_name_watercolor_wash: "Cat Air",
    faq_a_food_list_languages: "Daftar makanan bawaan awalnya berisi makanan Israel dengan nama Ibraninya. Di semua bahasa lain, setiap makanan ditampilkan dengan nama Inggrisnya, dan pencarian menemukan nama Inggris apa pun yang dikenalnya (misalnya 'broth' menemukan Clear soup); makanan yang hanya punya nama Ibrani tidak ditampilkan. Apa pun yang tidak ada di daftar bisa langsung ditulis dengan kata-katamu sendiri – perkiraan AI berfungsi di semua bahasa.",
    faq_q_food_list_languages: "Mengapa daftar makanan menampilkan nama dalam bahasa Inggris, dan lebih sedikit makanan, dalam bahasa saya?",
    settings_copyright_line: "© 2026 hak cipta dilindungi. aplikasi dikembangkan oleh eden zabari.",
    workout_ready_replace_btn: "Ganti",
    faq_a_sport_workout_ai: "Di Latihanku → ⋯ → Rencana dengan AI (dan saat tabel kosong, juga di kotak di samping rencana siap pakai). Jawab dengan beberapa ketukan – berapa kali seminggu, kapan, tempat, tingkat, dan tujuan, hampir semuanya juga punya \"Lainnya\" – lalu tambahkan satu baris bebas jika mau, misalnya lutut sensitif atau lari 5 km sebelum musim panas. AI membuat satu minggu penuh: jenis latihan, hari, jam, durasi, intensitas, gerakan, dan hari istirahat. Sebelum apa pun disimpan, ada pratinjau: \"Masukkan ke tabelku\" (menggantikan tabel atau sebagai tambahan), \"Saran lain\" (hingga 3 kali), atau \"Ubah jawaban\". Rencananya sengaja dibuat moderat, dan jika kamu menyebut nyeri atau cedera, kamu mendapat pilihan yang lembut dan saran untuk berkonsultasi dengan tenaga profesional. Ini memakai kuota AI yang sama dengan jadwal dan rutinitas: 5 kali gratis, dan 60 kali sebulan dengan Premium.",
    faq_q_sport_workout_ai: "Bagaimana cara membuat rencana latihan dengan AI?",
    workout_ai_add: "Tambahkan ke tabelku",
    workout_ai_again: "Saran lain",
