    workout_ai_when_ph: "mis. sepulang kerja, atau 17:30",
    workout_ai_working: "Membuat rencanamu…",
    faq_a_sport_workout_jar: "Setiap jenis latihan punya bintang dengan warnanya sendiri – lari merah muda, jalan kaki hijau, renang biru, dan seterusnya. Setiap latihan yang dicatat minggu ini, dari tabel atau terpisah, menjatuhkan bintangnya ke toples di bagian atas Latihanku, dan toples terisi menuju target mingguanmu (ketuk untuk mengubah target). Saat target tercapai, toplesnya bersinar. Toples kecil di sebelahnya menghitung berapa minggu berturut-turut toples itu penuh.",
    faq_q_sport_workout_jar: "Apa itu bintang berwarna dan toples di Latihanku?",
    faq_a_sport_workout_gcal: "Bisa – di ⋯ → Google Kalender (setelah Google Kalender terhubung di Pengaturan). Setiap latihan yang punya jam menjadi acara yang berulang tiap minggu di harinya, dan perubahan di aplikasi ikut memperbaruinya. Pengingat hanya datang dari aplikasi, jadi Google tidak menambahkan pengingatnya sendiri, dan latihan tidak pernah muncul dua kali di aplikasi. Mengetuk lagi hanya menghapus latihan dari Google Kalender.",
    faq_q_sport_workout_gcal: "Bisakah latihanku muncul di Google Kalender?",
    workout_gcal_btn: "Google Kalender",
    workout_gcal_error: "Google Kalender tidak bisa diperbarui – akan dicoba lagi di perubahan berikutnya",
    workout_gcal_not_connected: "Hubungkan Google Kalender di Pengaturan dulu",
    workout_gcal_off_toast: "Latihan dihapus dari Google Kalender",
    workout_gcal_on_toast: "Latihanmu sudah ada di Google Kalender",
    faq_a_sport_workout_reminder: "Bisa – di sebuah latihan, Pengingat: 10 menit, 30 menit, atau satu jam sebelumnya, atau waktu sendiri (latihannya perlu jam). Bunyinya sama seperti pengingat lain, sekali dan di satu tempat: di aplikasi jika sedang terbuka, kalau tidak di ponselmu. \"Selesai\" mencatat latihan di riwayat, dan \"Belum\" mengingatkan lagi 5 menit kemudian.",
    faq_q_sport_workout_reminder: "Bisakah aku mendapat pengingat sebelum latihan?",
    workout_reminder_30min: "30 menit sebelumnya",
    workout_reminder_label: "Pengingat",
    workout_reminder_need_time: "Tambahkan jam untuk mendapat pengingat",
    faq_a_sport_workout_share: "Di ⋯ → Bagikan, minggu latihanmu jadi gambar bergaya kaca dengan warna temamu, plus tautan halus ke aplikasi (di ponsel langsung ke menu berbagi, di komputer gambarnya disimpan). ⋯ → PDF untuk dicetak membuka halaman rapi berisi seluruh minggu, dengan kotak centang di samping setiap latihan dan gerakan – pilih \"Simpan sebagai PDF\" atau cetak. Rencananya juga muncul di laporan data di Pengaturan, bagian Olahraga.",
    faq_q_sport_workout_share: "Bagaimana membagikan atau mencetak minggu latihanku?",
    share_image_saved: "Gambar tersimpan – kamu bisa melampirkannya",
    share_save_image: "Simpan gambar",
    workout_pdf_btn: "PDF untuk dicetak",
    workout_share_btn: "Bagikan",
    faq_a_sport_workout_board: "Di ⋯ → Papan mingguan, setiap hari adalah kolom: seret latihan ke hari lain (di ponsel, tekan lama dulu). Di sebuah latihan, \"Juga di Rutinitas Saya\" memasukkannya ke rutinitasmu pada jam dan harinya, dan perubahan tetap sinkron dua arah; dari item di Rutinitas Saya, \"Tambahkan ke latihanku\" melakukan sebaliknya. ✓ di salah satu tempat terhitung di keduanya, dan di Hariku ia muncul sekali saja – di chip di sebelah air.",
    faq_q_sport_workout_board: "Bagaimana memindahkan latihan ke hari lain dan menghubungkannya ke Rutinitas Saya?",
    routine_in_workouts_btn: "Buka di latihanku",
