    workout_view_timeline: "Linimasa",
    faq_a_sport_workout_plan: "Di Pelacakan Latihan, bagian \"Latihanku\": + Latihan – jenis, hari, jam, durasi, intensitas, dan tempat (juga \"Lainnya\"). Latihan kekuatan, fungsional, dan renang bisa berisi daftar gerakan, dan Istirahat menandai hari istirahat. Kamu juga bisa mulai dari rencana siap pakai. Latihan hari ini tampil besar, dengan seluruh minggu di bawahnya; ✓ mencatatnya di riwayat latihan beserta intensitasnya. Di ⋯ kamu menetapkan target mingguan (latihan atau menit) – setiap latihan yang dilakukan menjatuhkan bintangnya ke dalam toples.",
    faq_a_sport_workout_today: "Di Hariku, di sebelah air, ada chip kecil yang menampilkan latihan hari ini – ketuk untuk membuka detail, ✓, dan ▶. ▶ memulai timer yang tetap berjalan di chip layar utama, dan \"Selesaikan\" mencatat latihan dengan waktu sebenarnya. Jika tantangan \"Dua minggu bergerak\" di New Me sedang berjalan, latihan yang tercatat langsung terhitung di sana.",
