    dictation_service_off: "Dikte dimatikan di browser atau komputer ini – nyalakan di pengaturan komputer, atau coba Chrome",
    faq_a_new_me_magic_themes: "Lima tema berkilau yang termasuk dalam New Me: Hutan Ajaib, Debu Bintang, Peri Mawar, Aurora Ajaib, dan Senja Emas. Pilih salah satu di dalam New Me (⚙️ Pengaturan > Warna) atau di Pengaturan > Tampilan & Layar, lalu kuas berkilau mewarnai layar dengan tema itu. Tema ajaib menambahkan kilauan di seluruh aplikasi dan di setiap ketukan. Kamu bisa kembali ke tema lain kapan saja.",
