    apptour_focus_text: "Semua menyingkir kecuali satu hal untuk saat ini – dengan ✓ besar. Lalu hal berikutnya muncul.",
    apptour_m_presets_text: "Makanan tersimpanmu di satu tempat: cari, baru dipakai, menurut waktu makan – dan ＋ menambahkannya ke hari ini.",
    apptour_night_text: "🌙 membuat seluruh aplikasi gelap; ☀️ mengembalikan siang.",
    apptour_noteline_text: "Tulis lalu ketuk ➤ – tersimpan di catatanmu. 📝 di awal beralih ke 🛒 belanja atau 🍎 makanan tersimpan.",
    apptour_search_text: "Catatan, belanja, kalender, resep, buku catatan, tujuan, tabel, dan buku – satu pencarian menemukan semuanya.",
    faq_a_new_me_ai_menu: "Sebelum menu, kuesioner menanyakan waktu makanmu dan jamnya (2 kali makan + camilan, 2 kali makan + makan malam ringan, atau keduanya), apakah kamu makan sesuatu yang kecil di malam hari dan jam berapa, apa yang tidak kamu makan, dan bagaimana kamu minum kopi atau teh. Lalu AI menyusun 3 pilihan untuk setiap waktu makan – masing-masing sesuai porsinya dalam sehari, jadi totalnya tetap tepat 1.300 atau 1.500 – plus ide minuman yang disimpan sebagai minuman tetapmu. Pilih hingga 2 favorit per waktu makan; pilihan dari menu asli ada tepat di bawahnya, dan di 🔄 Ganti muncul setelah menu pribadimu. 🔄 Pilihan lain menyusun set baru (3 kali per kuesioner). Untuk mengubah jawaban atau membuat menu baru kapan saja: ⚙️ Pengaturan → ✨ Menu pribadi (AI).",
    faq_q_new_me_ai_menu: "Bagaimana cara kerja menu pribadi di New Me?",
