    nm_ai_menu_drinks: "Minuman untukmu",
    nm_ai_menu_error: "Menu pribadi belum bisa dibuat sekarang – ini menu aslinya. Kamu bisa mencoba lagi, atau nanti dari ⚙️ Pengaturan.",
