    nm_sales_premium: "Termasuk seluruh Premium",
    nm_unlock_premium: "Seluruh Premium juga sudah terbuka.",
    settings_sub_status_newme: "Premium sudah termasuk dalam New Me kamu.",
    room_back_to_shelf: "Ke rak",
    faq_a_new_me_day_total: "Setiap hari pas sesuai rencana: makanan, sekitar 150 kalori untuk kopi dan minuman sepanjang hari, dan apa yang dipilih untuk malam hari – sesuatu yang kecil untuk dimakan atau sesuatu untuk diminum. Untuk malam hari, pilih hingga 3 yang disukai (misalnya pisang, yoghurt, atau 2 kotak cokelat hitam; atau teh herbal, teh dengan sedikit susu, atau susu hangat), dan kalorinya diambil dari makanan. Setiap pilihan seimbang dengan sendirinya: pilihan yang lebih kecil atau lebih besar, waktu makan yang ditiadakan, sarapan kecil dan makan kecil yang menyertainya, atau malam hari – selisihnya ditambahkan ke makanan atau dikurangi darinya, masing-masing sesuai ukurannya, dan di bawah setiap makanan tertulis berapa (+ atau −) dan apa yang bisa ditambah atau dikurangi. Makanan yang sudah dicentang tetap seperti yang dicatat. Di kuesioner, setiap makanan menunjukkan penyesuaiannya, dan kotak kecil menunjukkan makanan, minuman, malam hari, dan totalnya. Ingin yang lain hari itu? Jaga totalnya tetap sama kalorinya atau kurang.",
    faq_q_new_me_day_total: "Bagaimana satu hari New Me pas 1.300 / 1.500, dan di mana minuman dihitung?",
