    nm_less_line: "{n} kalori di makanan ini, agar hari ini pas {plan} – misalnya {ideas}",
    nm_less_line_late: "{n} kalori di makanan ini, untuk sesuatu yang kecil pukul {time} – misalnya {ideas}",
    nm_swap_balanced: "{n} kalori dibagi ke semua makanan, agar hari ini pas {plan}",
    books_quotes_chip: "Kutipan",
    faq_a_book_quotes: "Di rak kamar rahasia (Kutipan), atau lewat chip kecil 💬 Kutipan di Pojok Baca – daftarnya sama. Ketuk \"+ Kutipan\", tulis kalimatnya, lalu pilih buku dari Pojok Baca atau ketik judul lain lewat \"✏️ Lainnya\"; penulis opsional. ✏️ mengedit kutipan dan 🗑️ menghapusnya. Kutipan berupa pembatas buku yang digeser – 🎨 di atas menggantinya jadi foto atau dinding kartu.",
    faq_a_room_wish_jar: "Di rak kamar rahasia ada toples kaca untuk mimpi. Ketuk toples kecil di rak paling atas (atau Rak > Toples harapan) dan tulis seperti apa hidup yang kamu inginkan – sebebas mungkin, tanpa benar atau salah. Setiap harapan dilipat menjadi kertas dan jatuh ke toples. \"Ambil satu kertas\" membuka satu secara acak, dan setiap kertas juga bisa dibuka sendiri. Mulai kali kedua kamu membuka harapan yang sama, kamu bisa menjadikannya target dan memecahnya menjadi langkah kecil. Seminggu sekali, kertas berisi salah satu harapanmu muncul dengan lembut – tanpa tekanan, hanya pengingat ke mana kamu menuju.",
    faq_q_book_quotes: "Di mana menyimpan kutipan dari buku yang kusukai?",
