    room_wish_to_goal: "🎯 Jadikan target, dengan langkah kecil",
    room_wish_written: "Ditulis pada {date}",
    faq_a_saved_meals_page: "Makanan tersimpan punya halaman sendiri: Nutrisi & Metrik > ⭐ Makanan tersimpan (atau ⭐ di menu). Pencarian di atas menemukan makanan lewat nama atau bahan, \"Baru dipakai\" menampilkan yang baru kamu tambahkan, dan tab (Sarapan, Makan siang, Makan malam, Sup…) menampilkan tiap waktu makan. \"+ Hari ini\" menambahkan makanan ke Pelacak Makanan Harian hari ini, di slot kosong berikutnya. Ketuk sebuah makanan untuk mengedit atau menghapusnya, dan ＋ di atas menambahkan yang baru.",
    faq_q_saved_meals_page: "Di mana saya menemukan dan mengelola makanan tersimpan?",
