    presets_tab_snack: "Camilan",
    presets_tab_soup: "Sup",
    presets_tab_sweet: "Manisan",
    faq_a_notes_sticky_look: "Catatan adalah daftar pendek kartu kaca – 🎨 di atas Catatan mengganti tampilan seluruh Catatan: daftar, tombol hari di atas, dan jendela tempat menulis catatan – kaca, daftar bersih, kartu indeks, atau selotip washi. Catatan yang sedang diseret tetap mempertahankan tampilan dan warnanya sendiri. Ketuk teks catatan untuk membukanya – di sana kamu bisa mengeditnya, mengganti warnanya, dan melihat kapan terakhir ditulis. Ketuk ○ jika sudah selesai, dan × memindahkannya ke arsip (🗑️ di bawah daftar mengembalikannya). Seret lewat ⠿ untuk mengubah urutan, ke bawah “Nanti”, atau ke salah satu hari di atas. ! menandai catatan sebagai mendesak – catatan itu naik perlahan ke baris-baris pertama dengan label kecil “Mendesak”; ketukan berikutnya melepas tandanya.",
    faq_q_notes_sticky_look: "Bagaimana cara membuka, mengedit, atau menghapus catatan?",
    note_to_archive_btn: "Pindahkan ke arsip",
    faq_a_routine_clash: "Jika di jam itu pada hari yang sama sudah ada item, muncul dua pilihan: \"Ganti\" – item baru menempati jam itu dan Anda memilih jam lain untuk item sebelumnya (saat mengedit item yang sudah ada, jam lamanya disarankan, jadi keduanya tinggal bertukar), atau \"Keduanya\" – dua-duanya tetap di jam yang sama, satu di bawah yang lain. Jika harinya berbeda (misalnya satu Minggu–Kamis dan yang lain Jumat), tidak ada pertanyaan sama sekali.",
    faq_q_routine_clash: "Apa yang terjadi kalau saya menaruh item rutinitas di jam yang sudah terisi?",
    routine_clash_both: "✌️ Keduanya – dua-duanya pukul {time}",
    routine_clash_move_btn: "Pindahkan dan simpan",
    routine_clash_move_to: "Pindahkan \"{title}\" ke jam berapa?",
    routine_clash_replace: "🔄 Ganti – dan pindahkan \"{title}\" ke jam lain",
    routine_clash_title: "Pukul {time} sudah ada: {title}",
    faq_a_new_me_coffee: "Di bawah menu hari ini ada ringkasan singkat: berapa kalori semua makanan hari ini, berapa sisa untuk kopi dan minuman, dan tombol untuk kopi dan minuman yang dipilih – sekali ketuk langsung masuk ke Minuman. Di \"Pilih hingga 3 yang disukai\" di bawah tombol (dan di kuesioner), pilih apa yang tampil: air putih / air soda, teh herbal, minuman diet, hitam / americano (~5), teh dengan sedikit susu (~25), kopi berbasis air dengan maksimal 100 ml susu atau susu nabati (~50), cokelat panas ringan, susu hangat, atau kopi biasa / latte (~120).",
    faq_q_new_me_coffee: "Di mana menambahkan kopi, dan bagaimana tahu sisa untuk hari ini?",
