    faq_a_recipe_examples: "Di bawah resep Anda sendiri ada contoh resep: sarapan, salad, sup, hidangan utama, lauk pendamping, camilan, hidangan penutup, dan masakan vegan, masing-masing dengan waktu persiapan, kalori per porsi, dan berapa gram satu porsi. Ketuk resep untuk membukanya, dan \"Simpan ke Resep Saya\" membuat salinan Anda sendiri yang bisa diedit. Label kategori menyaring, dan mengetuk label yang sama sekali lagi menampilkan semuanya.",
    faq_a_recipe_grams: "Di dalam resep, di samping kalori, tertulis \"1 porsi ≈ X g\". Untuk resep Anda sendiri, isi \"Gram per porsi\" (dan waktu persiapan jika mau) di formulir resep: keduanya opsional, dan waktunya tampil di pita warna resep.",
