    recipes_examples_title: "Contoh resep",
    faq_a_recipe_scan_multi: "Bisa. Di \"Tambah Resep\", ketuk 📷 lalu pilih satu foto atau beberapa (maksimal 6; PDF juga bisa). Setiap foto muncul di daftar singkat tempat Anda memilih isinya: Semua, Bahan, atau Cara membuat, dan \"➕ Foto lain\" menambah lagi. Lalu ketuk \"✨ Pindai resep\": AI menggabungkan semuanya menjadi satu resep, berurutan dan tanpa baris ganda, dan dihitung sebagai satu kali pindai. Beberapa foto yang dipilih dari 📷 Foto di asisten AI juga terbuka di sini.",
    faq_q_recipe_scan_multi: "Bisakah saya memindai satu resep dari beberapa foto, misalnya bahan dan langkahnya terpisah, atau dua halaman?",
    recipe_scan_add_more: "➕ Foto lain",
