    faq_a_note_written_at: "Ketuk teks catatan untuk membukanya. Di dalamnya, di bawah teks, terlihat kapan catatan itu terakhir ditulis, lengkap dengan tanggal dan jam yang tepat. Hanya mengubah teksnya yang memperbaruinya: mengarsipkan lalu memulihkan, mencentang ✓, warna, atau memindahkan catatan tidak mengubahnya.",
    faq_q_note_written_at: "Bagaimana melihat kapan saya menulis sebuah catatan?",
    note_written_at: "Terakhir ditulis: {date}",
    faq_a_new_me_month: "Di tas ajaib → Kalender bulanan: setiap hari diberi warna sesuai jumlah makan yang dicentang, panah ‹ › berpindah antarbulan, dan di bawah kalender tertulis rata-rata kalori harian bulan itu. Mengetuk satu hari menunjukkan berapa kali makan yang dicentang dan berapa kalori yang dimakan hari itu.",
    faq_q_new_me_month: "Di mana saya bisa melihat bulan sebelumnya dan rata-rata kalori di New Me?",
    nm_month_avg: "Rata-rata bulan ini: {kcal} kalori sehari · hari tercatat: {n}",
    nm_month_day_empty: "Tidak ada catatan di hari ini.",
    nm_month_day_line: "Makan yang dicentang: {checks} · kalori: {kcal}",
    nm_extra_line_small: "{n} kalori untuk makanan ini, dari sarapan kecil – misalnya {ideas}",
    faq_a_new_me_small_breakfast: "Sarapan ringan (sekitar 170 kkal): pita spelt (maksimal 100 kkal) dengan olesan atau keju, serta sayuran – pilih hingga 3 yang disukai, misalnya 1 sendok teh selai cokelat, 1 sendok teh selai kacang, atau selembar keju (lemak maksimal 22%). Karena porsinya kecil, “Ditambah satu makan kecil” ikut menyertainya di jam lain (misalnya satu setengah jam kemudian, 11:30 → 13:00 – jam lain juga bisa dipilih): satu pita lagi & olesan, yoghurt protein & buah, rice cake & keju, sereal & susu, atau setengah pita & telur – hingga sekitar 200 kkal, dengan ✓ sendiri. Kalori yang masih tersisa dibagi ke waktu makan lainnya, dan setiap waktu makan menunjukkan berapa yang ditambahkan, jadi total harian tetap sesuai rencana. Pilih di kuesioner, atau ganti ke sarapan ini hanya untuk hari ini dengan 🔄 – misalnya saat sarapan terlambat.",
    faq_q_new_me_small_breakfast: "Apa itu \"sarapan kecil\" di menu New Me?",
