    faq_a_ai_icon: "Bisa – di Pengaturan > Tampilan & Layar. Gelembung lembut adalah bawaannya, dan dengan Premium Anda juga bisa memilih otak melayang atau robot.",
    faq_a_new_me_favorites: "Bisa. Di kuesioner (dan saat mengulanginya dari pengaturan), kamu bisa memilih hingga 2 opsi untuk setiap waktu makan. Yang pertama tampil di menu, dengan baris “atau” di bawahnya untuk yang kedua – ketuk untuk menggantinya hanya untuk hari ini. Dan kalau sarapan belum dimakan tepat waktu, “⏰ Nanti” memindahkannya ke jam yang lebih lambat hari itu, tanpa mengubah kalori.",
    faq_a_theme_mode: "Beberapa tema spesial paling cantik dalam mode gelap – Cat Air, Aurora, Barbie, dan dua tema berkilau – jadi memilih salah satunya mengubah aplikasi ke mode gelap, dan memilih tema lain (termasuk roket) mengubahnya ke terang. Hitam dan Abu-abu Tua tetap gelap. Anda selalu bisa menggantinya nanti lewat 🌙 di menu atau Mode Terang di pengaturan.",
    faq_a_water_month: "Di pelacakan air. Setiap entri di catatan hari ini menampilkan jam saat ditambahkan, dan \"Tabel bulanan\" membuka satu bulan penuh: setiap hari menunjukkan berapa liter yang diminum (✓ saat target harian tercapai), dan mengetuk satu hari menampilkan entri-entrinya beserta jamnya.",
    faq_q_ai_icon: "Bisakah ikon asisten AI diganti?",
