    dev_sim_panel_title: "PM – khusus untukmu",
    faq_a_new_me_weight_optional: "Tidak. Berat saat ini dan berat target di kuesioner sama-sama opsional. Jika penimbangan ditambahkan nanti (⚖️ Berat di \"Perjalanan saya\" di New Me, atau di pelacak berat), kemajuan dihitung dari penimbangan pertama.",
    faq_q_new_me_weight_optional: "Apakah berat badan wajib diisi di New Me?",
    nm_unlock_desc: "Menu, tantangan, dan perjalanannya sudah siap – selangkah demi selangkah, bersama.",
    nm_unlock_title: "New Me terbuka!",
    room_reveal_star: "Bintang baru menyala di teleskop di atap ✨",
    faq_a_room_records: "Pemutar piringan hitam ada di kamar sejak awal, di atas tunggul pohon dekat kursi santai. Piringannya membuka klip resmi lagu-lagu hits besar dari beberapa tahun terakhir di YouTube, dan di bawahnya ada lima melodi tenang yang diputar langsung di kamar – piringan berputar selama diputar, dan \"⏹ Berhenti\" mematikan musiknya.",
    faq_a_room_roof_gifts: "Keduanya datang dengan kunci ke-8. Mengetuk teleskop memungkinkan kamu mengintip lewat teleskop itu: langit malam dari dekat – geser (atau pakai panah) untuk melihat sekeliling – dan tantangan yang sudah selesai membentuk rasi bintang di dalamnya, satu bintang untuk tiap tantangan; mengetuk bintang menunjukkan tantangan yang mana. Mengetuk peti kecil membukanya – untuk sekarang masih kosong – dan ketukan lagi menutupnya.",
    faq_q_room_records: "Apa yang ada di pemutar piringan hitam di kamar rahasia?",
    faq_q_room_roof_gifts: "Apa itu teleskop dan peti di atap?",
