    room_chest_letter_1: "Setiap langkah kecil di jalan ini nyata – dan semuanya berarti.",
    room_chest_letter_2: "Bersikap baik pada diri sendiri adalah bagian dari jalan, bukan jeda darinya.",
    room_chest_letter_3: "Ada hari yang lebih ringan dan ada yang lebih berat. Tetap hadir di keduanya adalah kekuatan yang sesungguhnya.",
