    faq_a_new_me_preview: "Bisa. Halaman New Me dibuka dengan video singkat tentang apa yang terjadi di dalamnya: kuesioner, lampu di lorong, tas ajaib, tantangan, dan kunci. Di bawahnya ada semua yang termasuk, sekilas satu hari, dan jawaban singkat.",
