    ai_chat_food_edit: "✏️ Perbaiki kalori / protein",
    ai_chat_food_invalid: "Kalori harus berupa angka di atas 0",
    ai_chat_food_updated: "Diperbarui:",
    faq_a_ai_chat_food_fix: "Bisa. Di bawah jawaban di obrolan, ketuk ✏️ Perbaiki kalori / protein, ubah angkanya, lalu ketuk Simpan. Hanya yang baru ditambahkan yang berubah – meski sudah tergabung ke camilan yang sudah ada. AI bisa salah, jadi ada baiknya dicek sebentar.",
    faq_a_new_me_home_btn: "Jika punya New Me, 💎 kecil di samping mode fokus di bagian atas layar utama membuka menu hari ini. Makanan hari ini juga muncul di Hariku, masing-masing dengan ✓.",
    faq_a_routine_item_days: "Bisa. Ketuk item di Rutinitas Saya dan pilih harinya di 📅 Hari – misalnya hanya Senin sampai Jumat. Di hari lain item itu tidak muncul di Hariku dan tidak punya ✓; di Rutinitas Saya item tetap ada, lebih pudar, dengan harinya di sebelahnya. Kartu yang bertanya tentang item setelah 3 hari tanpa ✓ hanya menghitung hari milik item itu.",
    faq_q_ai_chat_food_fix: "Bisakah memperbaiki kalori atau protein setelah asisten mencatat makanan?",
    faq_q_new_me_home_btn: "Di mana New Me di layar utama?",
    faq_q_routine_item_days: "Bisakah satu item di Rutinitas Saya hanya ada di hari tertentu?",
    routine_item_days_label: "📅 Hari",
    home_note_meal_ph: "Cari makanan tersimpan…",
    menu_quick_search: "Pencarian cepat",
    nm_times_hint: "Tips: kamu bisa mengatur jam paling lambat biasanya kamu makan untuk tiap waktu makan – misalnya 9:00 kalau sering makan sekitar jam 8.",
    room_game_marquee: "Di perjalanan – berhenti dan nikmati",
    room_sand_erase_aria: "Gosok untuk menghapus tulisan",
    faq_a_home_note_line: "Tulis di baris di tengah layar utama lalu ketuk ➤ (atau Enter) – catatan tersimpan di Catatan. Ketuk 📝 di awal baris dan ia berubah menjadi 🛒: lalu yang Anda tulis masuk ke Daftar Belanja. Ketuk sekali lagi untuk 🍎: ketik beberapa huruf, makanan tersimpan yang cocok muncul, dan satu ketukan mencatatnya di makanan hari ini. Dengan 🎤 Anda cukup mengucapkannya.",
    faq_a_night_mode: "Buka menu ☰ dan ketuk 🌙 di atas – seluruh aplikasi menjadi gelap. ☀️ di tempat yang sama mengembalikan siang. Ini juga ada di Pengaturan, di bawah Mode Terang.",
    faq_q_home_note_line: "Bagaimana cara menulis catatan cepat dari layar utama?",
    faq_q_night_mode: "Bagaimana cara beralih ke mode malam?",
    menu_day_mode: "Mode siang",
    menu_night_mode: "Mode malam",
    faq_a_secret_room_yoga: "Di ujung jalan setapak di hutan ada gerbang bercahaya, dan di baliknya, di dekat air terjun, makhluk-makhluk hutan – Lumi, Puffi, Nixie, dan Sparklet – duduk di atas matras mereka membentuk setengah lingkaran, sementara Flora, sang guru yoga, duduk menghadap mereka di satu-satunya matras di atas batu. Ketuk Flora: ia membuka mata, semuanya mendekat, dan percakapan dimulai perlahan, dengan waktu untuk membaca – Flora menanyakan kabar semuanya, setiap makhluk menjawab atas namanya sendiri (dengan gambar kecil si pembicara di samping setiap baris), lalu ia bertanya padamu bagaimana rasanya bersama orang-orang terdekat. Percakapan berlanjut sesuai jawabanmu – orang baik, seseorang yang sulit, atau sedikit kesepian. Setiap jalan berakhir dengan misi kecil (bisa langsung masuk ke Hariku; kalau misinya menulis sesuatu, ada tempat untuk menulisnya, dan tulisannya tersimpan di buku harian ajaib) dan pose dengan tiga napas bersama. ↩ kembali satu langkah dan ✦ memulai percakapan baru. Kunci berikutnya membuka air terjun: duduk di batu membuat semuanya menghilang, dan hanya suara air yang tersisa. Saat membungkuk di atas kolam, sebuah pertanyaan muncul dari air – apa yang akan dilakukan dirimu yang sejati hari ini? – dan jawabannya menjadi tugas kecil di Hariku. Ini momen yang hangat, bukan pengganti bicara dengan profesional.",
    faq_q_secret_room_yoga: "Apa yang terjadi di yoga hutan?",
