    nm_time_hour: "Jam",
    nm_time_minutes: "Menit",
    routine_time_taken: "Sudah ada sesuatu di jam ini: {title}",
    faq_a_new_me_times: "Di kuesioner awal, dan kapan saja di pengaturan New Me → \"Jam makan\". Jika rutinitas sudah punya jam makan, jamnya diambil dari sana – dan waktu makan di rutinitas bisa disembunyikan, dengan waktu makan New Me ditampilkan sebagai gantinya. Jika belum, pilih berapa kali makan sehari (2 kali makan + camilan / 2 kali makan + makan malam ringan / 2 kali makan + camilan + makan malam ringan) dan kapan masing-masing. Dengan \"2 kali makan + camilan\", itu berarti makan siang pukul 11:30, camilan pukul 16:00, dan makan malam pukul 19:00 (semuanya bisa diubah). Inilah jam makan di mana-mana: di lorong, di Hariku, di Rutinitas Saya, dan di pengingat. Apa pun pilihannya, kalori harian tetap sama: kalori waktu makan yang ditiadakan dibagi ke waktu makan lainnya.",
    faq_q_new_me_times: "Bagaimana cara mengatur jam makan di New Me?",
    nm_times_count: "Berapa kali makan sehari?",
    nm_times_from_routine: "Ya, ambil dari rutinku",
    nm_times_hide: "Sembunyikan waktu makan di rutinku dan tampilkan waktu makan New Me sebagai gantinya",
    nm_times_later: "Nanti",
    nm_times_manual: "Tidak, pilih di sini",
    nm_times_none_found: "Rutinmu belum punya waktu makan – pilih di sini berapa kali dan kapan.",
    nm_times_q: "Apakah rutinmu punya jam makan yang tetap?",
    nm_times_saved: "Jam makan disimpan",
    nm_times_title: "Jam makan",
    faq_a_routine_exact_time: "Bisa. Saat kamu menjelaskan rutin ke AI dengan jam yang tepat (misalnya \"16:10 trading\"), jam itu disimpan persis begitu – tidak dibulatkan ke jam penuh. Apa pun yang tertulis di rutinmu selalu tampil di papan, meski jamnya tidak dipilih di pengaturan jam, dan menghapus jam yang berisi sesuatu akan bertanya dulu. Kamu juga bisa mengubah jam secara manual: sentuh jam di jendela item lalu pilih jam dan menitnya.",
    faq_q_routine_exact_time: "Bisakah rutinku punya jam yang tepat, seperti 16:10?",
