    routine_daysoff_which: "Hari apa saja?",
    faq_a_secret_room_diary: "Hanya kamu. Halaman buku harian disimpan di akunmu, jadi ada di setiap perangkat, dan tidak ada orang lain yang bisa melihatnya. Buku harian ajaib di atas meja di kamar rahasia membukanya, begitu juga buku harian di pojok musik. Di bawah halaman baru ada tabel bulanan yang terlipat: titik menandai setiap hari yang punya halaman, dan menyentuh sebuah hari membuka halaman-halamannya – di sana halaman juga bisa dihapus. Setelah buku harian terbuka, buku harian juga bisa ditambahkan ke menu utama – lewat sakelar di dalam buku harian atau di pengaturan New Me.",
    faq_a_secret_room_places: "Setiap pintu masuk di gerbang hutan terbuka dengan kuncinya sendiri. Di baliknya: teras menghadap laut (di meja kecil ada lampu Aladin – sekali sentuh, roh hutan muncul darinya dalam kabut ajaib, berputar-putar, lalu memulai percakapan tentang harapanmu – lihat “Apa yang dilakukan jin lampu?”), gitar dan buku harian (gitar memainkan melodi singkat yang tenang dan berhenti sendiri, dan masing-masing dari tiga piringan hitam yang tergantung di pohon memainkan melodi ajaibnya sendiri – sentuh lagi untuk berhenti – dan buku harian di atas tunggul pohon untuk menulis), ruang bernapas (danau yang tenang saat matahari terbenam – lentera teratai mengapung di atas air: sentuh, tulis harapan, lalu lentera itu hanyut bersamanya, jauh ke tengah danau; dengan tongkat sihir kamu bisa menulis di pasir apa yang ingin kamu lepaskan, dan tulisan itu tetap ada sampai kamu menghapusnya dengan jari) dan jalan setapak di hutan (terbuka di malam hari, dan sentuh lentera untuk berganti ke siang; dari dahan besar tergantung ayunan ajaib, bangku untuk duduk, dan sentuh papan untuk melihatnya dari dekat – papan berisi enam pertanyaan kecil untuk dicentang). Pintu masuk yang terkunci menunjukkan berapa kunci lagi. Di ujung jalan setapak, gerbang bercahaya mengarah ke yoga di dekat air terjun – dan dari sana, ke air terjun itu sendiri.",
    faq_q_secret_room_diary: "Siapa yang bisa melihat buku harian?",
    faq_q_secret_room_places: "Apa yang ada di balik pintu-pintu di lorong?",
