    dev_weather_preview_label: "Pratinjau – hanya di akunmu:",
    faq_a_ai_chat: "Ketuk gelembungnya dan obrolan akan terbuka. Pilih apa yang mau dilakukan – sesuatu untuk kalender, apa yang dimakan, foto resep, atau tabel baru – atau tulis saja, dan asisten akan memahaminya sendiri. Untuk kalender bisa dipilih sekali, setiap minggu, atau setiap hari. Jawabannya muncul di obrolan, dan dari sana bisa lanjut ke hal lain atau membuka kalender / yang dimakan.",
    faq_a_new_me_hall: "New Me terbuka di gerbang hutan ajaib, dan setiap pintu masuk di sana adalah sebuah tempat: pintu bundar di pohon raksasa menuju kamar rahasia, batang kayu berongga ke teras menghadap laut, rumah jamur ke gitar dan buku harian, lengkung dedalu kecil ke ruang bernapas, lengkung dedalu besar ke jalan setapak di hutan, dan lengkung bunga bertangga naik ke atap bintang setelah atap itu terbuka. Pintu masuk yang terkunci menampilkan gembok. Karaktermu, Me, melayang di jalan setapak, dan tombol permainan ada di sekelilingnya: misi berikutnya, tantangan minggu ini, tas ajaib berisi seluruh New Me, peta dunia, dan alat-alat. Menyentuh kunci di bagian atas menjelaskan cara mendapatkan kunci.",
    faq_a_new_me_routine_meals: "Saat waktu makan sudah diatur di New Me dan Rutinitas Saya juga berisi waktu makan, New Me bertanya apakah waktu makan itu perlu disembunyikan dan diganti dengan waktu makan New Me – agar tidak ada yang muncul dua kali. Lalu Rutinitas Saya menampilkan waktu makan New Me pada jamnya, dengan 💎 dan ✓; mengetuk nama sebuah makanan membuka jendela untuk memilih makanan lain atau mengubah jamnya, langsung di atas rutinitas. Tidak ada yang dihapus: semuanya kembali lewat ⚙️ Pengaturan → Makan di rutinitas di New Me, atau dengan mematikan “Sinkronkan dengan New Me” di ⚙️ Rutinitas Saya. Tanpa New Me yang aktif, semuanya kembali dengan sendirinya.",
    faq_a_room_computer: "Ini obrolan kecil yang dimulai dengan “Bagaimana harimu sejauh ini?” – baik, sibuk, atau berat – lalu berjalan bersamamu langkah demi langkah, sampai satu misi kecil di akhir (yang juga bisa langsung masuk ke Hariku). Jawaban bisa diketuk atau ditulis bebas – yang ditulis akan dihubungkan ke jawaban yang paling mirip. “↩ Kembali” mundur satu langkah supaya bisa menjawab berbeda, dan “Obrolan baru” memulai dari awal kapan saja. Setelah hari yang sibuk atau berat, kamu bisa kembali ke komputer nanti di hari yang sama: “Aku kembali...” melanjutkan percakapan. Lampu hijau di bawah mematikan dan menyalakan komputer. Hanya pilihan yang disimpan, hanya di perangkat ini, dan hanya sampai akhir hari.",
    faq_q_ai_chat: "Bagaimana cara berbicara dengan asisten?",
