    dictation_btn_aria: "Bicara dan langsung tertulis",
    dictation_mic_denied: "Mikrofon diblokir – izinkan lewat 🔒 di samping alamat di browser, atau di pengaturan ponsel",
    faq_a_dictation: "Bisa – ketuk mikrofon 🎤 di sudut catatan cepat atau halaman tulis di buku catatan, lalu bicaralah: kata-kata langsung tertulis saat Anda bicara, dalam bahasa aplikasi. Ketuk lagi untuk berhenti. Pertama kali, browser meminta izin memakai mikrofon. Berfungsi di Chrome / Android dan Safari di iPhone. Di komputer kamu butuh mikrofon dan browser seperti Chrome, Edge, atau Safari – kalau ada yang kurang, pesannya menyebutkan persis apa.",
    faq_q_dictation: "Bisakah saya berbicara alih-alih mengetik?",
    faq_a_secret_room: "Kamar yang hanya milikmu, di dalam New Me – sebuah rumah di dalam pohon raksasa. Kamu melihat satu dinding setiap kali dan berputar dengan panah (atau geser). Kunci pertama datang setelah ✓ pada makanan di 3 hari berbeda dan membuka pintu – sekaligus seluruh kamar: komputer, permainan, pemutar piringan hitam, rak dengan perpustakaan di dalamnya, dan kucing. Setelah itu, setiap tantangan yang selesai (termasuk tantangan minggu ini) memberi kunci yang membuka tempat berikutnya: atap bintang, teras menghadap laut, gitar dan buku harian, ruang bernapas, jalan setapak di hutan dengan yoga, air terjun, dan kejutan di atap – dan tantangan ke-8 membawa botol dari laut berisi surat dari masa lalu. Saat sesuatu terbuka, panah menunjukkan jalannya. Pintu kecil di bagian bawah mesin permainan juga terbuka – untuk sekarang lemari di baliknya masih kosong. Di atap bintang, bintang yang diketuk jatuh seperti bintang jatuh, dan kucing duduk di atas bantal.",
