    home_streak_days: "{n} hari berturut-turut",
    home_streak_title: "Hari berturut-turut dengan setidaknya satu ✓",
    settings_good_things_label: "\"3 hal baik\" di malam hari",
    settings_weather_hint: "Hujan, awan, atau salju di latar layar utama, sesuai cuaca di tempat Anda. Lokasi perkiraan tetap di perangkat ini dan dicek lewat server kami ke MET Norway.",
    settings_weather_label: "Cuaca di langit layar utama",
    weather_failed: "Cuaca belum bisa dicek sekarang.",
    weather_location_denied: "Tidak ada akses lokasi – izinkan di pengaturan browser lalu coba lagi.",
    faq_a_home_focus: "Ketuk ◎ di atas layar Beranda: semuanya menghilang kecuali satu hal untuk sekarang – yang berlangsung pada jam ini, atau hal berikutnya di daftar hari ini – dengan ✓ besar, dan Catatan Cepat. Setelah ✓, hal berikutnya muncul. Ketuk 'Mode fokus ✕' di atas untuk mengembalikan semuanya.",
    faq_a_home_search: "Buka menu ☰ – pencarian ada paling atas. Ketik minimal 2 huruf: hasilnya berasal dari catatan, daftar belanja, kalender, resep, buku catatan (judul dan teks halaman), tujuan, tabel, dan buku Anda, dikelompokkan per jenis – ketuk salah satu untuk langsung ke sana.",
    faq_a_my_day: "Hariku menggabungkan yang dulu bernama Sekilas Hari Ini dan Rutinitas Saya dalam satu linimasa. Di bagian bawah layar Beranda terlihat berapa yang sudah selesai, apa yang sekarang atau berikutnya (dengan ✓ cepat), dan di samping judul ada segelas air dengan +1. Ketuk (atau geser ke atas) untuk membuka seluruh hari: di atas yang tanpa jam, lalu semuanya per jam – tugas, acara, dan rapat dari kalender, jadwal tetap mingguan, rutinitas hari ini, langkah kecil target Anda, dan makanan New Me – dengan garis untuk sekarang. Saring menurut Tugas, Rutinitas, atau Rapat & acara. ✓ di sini sama dengan ✓ di tempat lain (Rutinitas Saya, Target Saya, kalender) dan membuat bunga aster mekar di sudut. 'Ubah rutinitas' membuka Rutinitas Saya (juga ada di menu), dan '＋ Tambah untuk hari ini' menambahkan tugas untuk hari ini. Mengetuk judul \"Hariku\" (atau garis kecil di atas) menutupnya lagi.",
    faq_q_home_focus: "Apa itu mode fokus?",
    faq_q_home_search: "Bagaimana mencari di seluruh aplikasi?",
