    reminder_closed_app_hint: "📱 Saat aplikasi ditutup, yang berbunyi adalah suara notifikasi ponsel itu sendiri – bisa dibuat lebih keras di pengaturan notifikasi ponsel untuk aplikasi atau browser (suara dan 'muncul di layar').",
