    faq_a_new_me_tour: "Tepat setelah membeli dan mengisi kuesioner singkat, tur singkat menunjukkan permainannya: bilah atas, misi berikutnya, alat di kedua sisi, tantangan minggu ini, tas ajaib, peta dunia, karaktermu Me, dan pintu 1 ke kamar rahasia. Tur bisa ditonton lagi kapan saja dari ⚙️ Pengaturan > 🧭 Tur New Me – di sana nama lengkap dari kuesioner juga bisa diubah. Sebelum membeli, New Me menampilkan 🔒 di menu, dan mengetuknya membuka halaman berisi semua yang termasuk.",
