    faq_a_new_me_advanced: "Mode lanjutan terbuka bersama hadiah, setelah ke-20 tantangan, dan bisa dinyalakan atau dimatikan di 🎁 Hadiahmu. Mode ini memberi New Me tampilan emas, menyusun menu dengan bebas – setiap penggantian menampilkan semua pilihan tanpa batas kalori – dan layar 📊 Statistik lanjutan: kalori 30 hari terakhir dibandingkan rencana, hari baik menurut hari dalam seminggu, tren berat badan dengan perkiraan kapan target tercapai, rata-rata check-in malam, dan riwayat tantangan.",
