    nm_gift_title: "Hadiahmu",
    faq_a_new_me_letter_gift: "Di awal New Me (atau nanti, di Tantangan) bisa ditulis surat untuk dirimu di masa depan. Setelah disegel, surat itu tidak bisa dibaca atau diubah sampai terbuka: di dalam botol dari laut di kamar rahasia, atau di akhir ke-20 tantangan – di sana juga ada hadiah yang menunggu.",
    faq_q_new_me_letter_gift: "Apa itu surat dari masa lalu?",
    faq_a_new_me_challenges: "🏆 Tantangan berisi 20 tantangan: 10 besar (misalnya 5 hari tanpa gula, seminggu tanpa karbohidrat, atau turun 4 kg dalam sebulan – defisit kalori, latihan, dan tanpa gula setiap hari) dan 10 mini – kebiasaan kecil selama seminggu, seperti kopi kayu manis tanpa gula. Saat memilih tantangan, ada pertanyaan kapan mulai: hari ini, besok, minggu depan, atau tanggal lain. Satu tantangan besar dan satu tantangan mini bisa berjalan bersamaan. Tantangan yang berjalan tampil di paling atas menu dan di Hariku, dengan ✓ untuk hari itu. Setiap minggu tantangan memberi satu hari bebas (🍕) yang tidak memutusnya, dan hari yang tidak ditandai dihitung sebagai hari bebas – hari ini dan kemarin bisa ditandai. Beberapa hari tertandai otomatis: latihan 20 menit di Pelacakan Latihan, atau makanan di menu yang mendapat ✓. Setiap tantangan punya ⓘ berisi apa saja yang dihitung (misalnya daftar lengkap karbohidrat) – di tantangannya sendiri dan di sebelahnya di Hariku. Di bawahnya, 🌱 Pengembangan diri berisi 48 tantangan kecil selama satu minggu (tidak dihitung dalam 20 tantangan itu) – lihat “Apa itu tantangan minggu ini?”.",
    faq_q_new_me_challenges: "Bagaimana cara kerja tantangan di New Me?",
