    nm_letter_ph: "Di mana aku hari ini, ke mana aku ingin sampai, apa yang sulit bagiku soal makanan, apa yang ingin kukatakan pada diriku di garis akhir…",
    nm_letter_intro: "Ditulis sekarang lalu disegel – baru terbuka setelah semua {n} tantangan, untuk melihat seberapa banyak yang berubah sejak saat itu. Di mana aku sekarang? Apa tujuanku, dan apa yang sulit bagiku soal makanan?",
