    nm_ch_lose5_month_desc: "Tiga hal setiap hari: tetap di dalam anggaran kalori (defisit), satu latihan, dan tanpa gula tambahan. Yang dihitung harinya – bukan timbangan, yang bergerak dengan iramanya sendiri.",
