    nm_ch_completed_label: "tantangan selesai",
    nm_tile_challenges: "Tantangan",
    faq_a_workout_calories: "Ya. Setiap sesi olahraga mendapat perkiraan kalori yang terbakar – berdasarkan jenis, durasi, dan berat badan terakhir (untuk lari dan bersepeda juga berdasarkan kecepatan, jika jarak diisi). Angkanya muncul di daftar olahraga dan ringkasan bulanan (Terbakar), dan ditambahkan ke anggaran kalori hari itu: di Pelacak Makanan Harian, di Metrik Kalori dan Berat Badan, dan di lingkaran New Me. Ini perkiraan, jadi ditampilkan dengan ~.",
    faq_q_workout_calories: "Apakah olahraga dihitung dalam kalori harian?",
    faq_a_new_me_flexible_menu: "Bisa. Di kuesioner dan pengaturan, pilih berapa kali makan sehari – 2 kali makan + camilan / 2 kali makan + makan malam ringan / 2 kali makan + camilan + makan malam ringan – dan ➖ di kartu makanan menghapusnya (paling sedikit 3 tetap ada); '➕ Tambahkan lagi' mengembalikannya. Bagaimanapun juga kalori harian tetap sama: kalori waktu makan yang ditiadakan dibagi ke waktu makan lainnya, dan di bawah setiap makanan tertulis berapa yang ditambahkan dan apa yang bisa menyertainya. ✏️ Ubah pada makanan membuka teksnya – ubah sesukamu (mis. tanpa roti atau tambah satu telur) dan AI menghitung ulang kalori dan proteinnya. 🔄 Ganti menawarkan pilihan dari menu, ⭐ Tersimpan, dan ✨ Tulis; setiap perubahan bisa untuk hari ini saja atau mulai sekarang. Di akhir 'Sepanjang hari' ada ➕ Tambah makanan – tulis apa yang dimakan di luar menu, lalu AI menghitung dan menambahkannya ke hari ini (✕ menghapusnya).",
    faq_q_new_me_flexible_menu: "Bisakah mengubah jumlah makan di New Me, atau makan menu sendiri?",
