    apptour_nb_inside_title: "Di dalam tas",
    faq_a_recipe_to_preset: "Bisa. Buka resepnya dan ketuk '⭐ Tambah ke Makanan Tersimpan'. Nama, kalori per porsi (atau totalnya jika porsi tidak diatur) dan bahan-bahannya sudah terisi, dengan kategori yang cocok – periksa, ubah sesukamu, lalu simpan. Setelah itu tinggal satu ketukan di Pelacak Makanan Harian dan di tambah cepat 🍎.",
