    vision_focus_ribbon: "🎯 Target bulan ini",
    vision_tagline: "Target besar, langkah kecil.",
    faq_a_app_tour: "Tur terbuka otomatis sekali, saat pertama kali masuk. Tur dimulai dengan bagian-bagiannya – ketuk salah satu untuk langsung ke sana – lalu menunjukkan semua bagian aplikasi (layar utama, asisten AI, dan setiap item di menu) dan lima grup Pengaturan, masing-masing dengan penjelasan singkat, dan mengintip ke dalam beberapa di antaranya (misalnya jalur tujuan contoh, tas, dan Google Calendar). Lanjut untuk maju, Kembali untuk mundur, Lewati bagian ini untuk pindah ke bagian berikutnya, dan ✕ menutup tur. Kamu bisa memutarnya lagi kapan saja dari Pengaturan > Bantuan & Penggunaan > Tur Aplikasi, dan melanjutkan dari tempat terakhir. Lanjut dan Kembali selalu ada di tempat yang sama di bagian bawah layar, dan di komputer tombol panah keyboard juga bisa dipakai.",
    faq_q_app_tour: "Bagaimana cara melihat tur aplikasi lagi?",
    apptour_done_text: "Ada pertanyaan? Bantuan & FAQ di Pengaturan menjawab semuanya, dan tur ini selalu ada di Bantuan & Penggunaan.",
    apptour_done_title: "Itu saja! 🎉",
