    apptour_connect_title: "Semuanya terhubung",
    apptour_s_support_text: "Bantuan & FAQ, hubungi kami, bagikan aplikasi – dan tur ini, kapan saja.",
    apptour_s_account_text: "Premium, kata sandi, laporan pribadi PDF, sinkronisasi Google Calendar, dan penghapusan akun.",
    apptour_s_notifications_text: "Notifikasi pengingat dan suaranya. '⏰ Belum' pada pengingat berfungsi seperti tunda (snooze) pada alarm: mengingatkan lagi setiap 5 menit.",
    apptour_s_personalization_text: "Negara, jumlah makan dan camilan per hari, kapan bulan keuangan dimulai, dan apa yang tampil di layar utama.",
    apptour_s_appearance_text: "Bahasa, mode terang atau gelap, tema, font, warna teks, aksesibilitas, dan ukuran tampilan.",
