    apptour_m_calories_link: "Pelacakan berat badan juga ada di sini – dibagikan dengan New Me dan target berat badan di Target Saya.",
    apptour_m_calories_text: "Statistik kalori harian, mingguan, dan bulanan dibandingkan target.",
    apptour_m_meals_link: "Makanan tersimpan, daftar makanan, dan perkiraan AI; New Me, tambah cepat, dan minuman juga dihitung di sini.",
    apptour_m_meals_text: "Catat setiap makanan dengan kalori dan protein, hari demi hari.",
