    apptour_m_notes_link: "Seret catatan ke Hari Ini, Besok, atau tanggal lain untuk menjadikannya tugas; catatan yang dihapus menunggu di 🗑️ arsip.",
    apptour_m_notes_text: "Catatan dan ide dalam satu daftar.",
    apptour_m_tables_link: "Asisten AI bisa merancang tabel secara otomatis.",
