    apptour_m_study_link: "🪄 Pembagian Cerdas, di kartu ✅ Tugas, memecah tugas besar menjadi langkah-langkah di kalender.",
    apptour_m_study_text: "Tasmu: satu kantong untuk setiap bagian hidup – berisi buku catatan, tabel, dan tugas.",
    apptour_m_vision_link: "📅 pada sebuah tonggak memasukkannya ke kalender; langkah kecil dan tugas tantangan harian muncul di Hariku, dan progres juga bisa mengikuti angka atau berat badanmu.",
    apptour_m_vision_text: "Targetmu sebagai jalan dari langkah-langkah kecil – dengan langkah hari ini di paling atas. Ayo intip ke dalam 👇",
    apptour_m_myweek_link: "Sinkron dengan Google Calendar (di Pengaturan).",
    apptour_m_myweek_text: "Kalender bulanan, tugas mingguan berulang dengan pengingat, dan semua acara bertanggal. Ditambah buku agenda kertas untuk rapat minggu ini 🤝.",
    apptour_m_newme_link: "Semuanya dihitung di Pelacak Makanan Harian dan Hariku; berat badan dibagikan dengan Metrik Kalori dan Berat Badan.",
    apptour_m_newme_text: "Rencana makan 1.300 / 1.500 kalori di dalam dunia permainan ajaib: menu hari ini dengan ✓, penggantian dengan tiga cara – dari menu, dari makanan tersimpan, atau dengan menulis ke AI apa yang dimakan, lalu AI menghitung kalorinya – daftar belanja, pengingat makan, dan perjalanan progres dengan pencapaian, ukuran tubuh, dan foto. Ditambah 🏆 20 tantangan – dengan hadiah di akhir – dan tantangan minggu ini.",
    apptour_ai_table_text: "Jelaskan tabel yang dibutuhkan – AI merancang kolomnya (Premium).",
