    apptour_ai_photo_text: "Foto resep tertulis – AI mengisikan resep baru untuk Anda.",
    apptour_ai_schedule_link: "Muncul di kalender dan di Hariku.",
    apptour_ai_schedule_text: "Jelaskan rencana dengan kata-kata biasa, sekali atau berulang – langsung masuk ke kalender.",
    apptour_ai_food_link: "Langsung masuk ke Pelacak Makanan Harian dan total hari ini.",
    apptour_ai_food_text: "Ketik apa yang dimakan – kalorinya diperkirakan dan dicatat otomatis.",
    apptour_newme_short_text: "Membuka New Me – menu hari ini langsung ada di layar utama.",
    apptour_ai_link: "Lencana kecil 1 di atasnya adalah pengingat harian 'hal terpenting hari ini'.",
    apptour_ai_text: "Tulis dengan kata-kata sederhana dan asistenmu mengurus sisanya: mencatat kalori, memasukkan rencana ke kalender, membaca resep dari foto, dan membuat tabel.",
    apptour_quicknote_link: "📝 dan 🛒 membuka daftar lengkap; 🍎 mencatat makanan tersimpan di Pelacak Makanan Harian.",
    apptour_quicknote_text: "Tulis sesuatu dengan cepat – ke Catatan atau langsung ke Daftar Belanja.",
    apptour_routine_link: "Sebuah kebiasaan bisa otomatis mencatat latihan di Pelacakan Latihan.",
    apptour_routine_text: "Rutinitas harian per jam, dalam tab (anak, belajar, kerja…). Centang ✓ setiap hari untuk membangun kebiasaan dan rentetan; 📅 menampilkan sebulan penuh.",
    apptour_premium_text: "Membuka asisten AI lengkap, tema, font, Tas Saya, dan lainnya.",
    apptour_note_text: "Catatan tempel untuk seminggu penuh. Di dalamnya, roda gigi ⚙ menambahkan daftar centang 1–3 baris dan mengubah warna serta gayanya.",
    apptour_peek_link: "Tugas dari AI, kalender, langkah target, dan Google Calendar semuanya muncul di sini – plus kalori hari ini 🔥 dan 🎯 target bulan ini.",
