    table_select_option_delete_confirm: "Opsi ini digunakan di {count} baris. Hapus? Sel-sel tersebut akan dikosongkan.",
    table_select_option_delete_title: "Hapus opsi",
    faq_a_other_manual_option: "Di mana pun Anda memilih dari daftar opsi, selalu ada '✏️ Lainnya' - pilih itu dan ketik persis apa yang Anda butuhkan. Di tabel dengan kolom pilihan (misalnya 'Hubungan' di tabel hadiah), ketuk selnya, pilih '✏️ Lainnya', ketik nilainya (misalnya 'Keponakan'), lalu ketuk Tambah - nilai itu disimpan sebagai opsi baru di kolom tersebut, jadi lain kali sudah ada di daftar. Tanda × kecil di samping setiap opsi dalam daftar itu menghapus opsi tersebut dari kolom. Saat memilih ikon tabel, tersedia banyak ikon (termasuk catatan tempel berwarna). Cara yang sama berlaku untuk kategori makanan tersimpan, kategori resep, kategori pengeluaran berulang (disimpan sebagai kategori pribadi baru) dan kategori target di Target Saya.",
