    nm_extras_title: "Juga dimakan hari ini",
    nm_drinks_total: "{n} / ~{kcal} kkal",
    nm_drink_missing: "Masukkan nama minuman dan kalorinya",
    nm_drink_more: "+ Minuman lain",
    nm_drink_add: "Tambah",
    nm_drink_name_ph: "Minuman (mis. jus)",
    nm_drinks_hint: "Cukup ketik nama minumannya – kalorinya dihitung otomatis, dan angkanya bisa diubah.",
    nm_slot_drinks: "Minuman",
    faq_a_new_me_tracking: "Ketuk misi berikutnya di bagian atas New Me, lalu ✓ Sudah makan untuk menandai makanan berikutnya sudah dimakan – menu lengkap dengan ✓ di setiap makanan ada di Sepanjang hari, di samping, dan makanan hari ini juga muncul di Hariku di layar utama – mengetuk salah satunya di sana (atau mengarahkan mouse ke atasnya) menunjukkan persis apa yang perlu dimakan, dengan ✓ dan Ganti. Semuanya tersinkron dengan Pelacak Makanan Harian: makanan dari rencana, minuman, dan apa pun yang ditambahkan di tempat lain (misalnya kopi dari tambah cepat) dihitung bersama di New Me dan di Hariku – tidak ada yang sudah diketik akan tertimpa, dan menghapus ✓ hanya menghapus bagian New Me. Saat semua makanan hari ini sudah ditandai, ada perayaan kecil. Di “Minuman”, catat minuman hari itu – totalnya sampai ~150 kkal, artinya sekitar 3 minuman masing-masing sampai ~50 kkal. Cukup ketik nama minumannya dan kalori terisi otomatis oleh AI. Dua baris kopi/teh juga punya kolom “Susu? Berapa banyak?” (misalnya “sedikit” atau “50 ml”), dan perhitungannya diperbarui; angkanya bisa diubah sebelum ditambahkan maupun sesudahnya. Minuman yang punya nama dan kalori tersimpan otomatis begitu beralih ke hal lain – mengetuk Tambah itu opsional. Ketuk ☆ di samping minuman untuk menyimpannya sebagai minuman rutin – minuman rutin muncul sebagai tombol di bagian atas kartu Minuman, dan satu ketukan menambahkannya ke hari itu. ⭐ menyimpan makanan sebagai makanan tersimpan. “Tabel harian” menampilkan apa yang dimakan beserta kalori dan protein. 💎 kecil di samping mode fokus di bagian atas layar utama langsung membukanya. Nilai kalori dan protein adalah perkiraan AI dan bisa mengandung kesalahan. Tidak habis? Di bawah makanan yang sudah ditandai, “Tidak habis?” mengurangi seperempat, setengah, atau tiga perempat porsi – atau apa yang ditulis, sesuai perhitungan – dan kalori hari itu diperbarui.",
    faq_q_new_me_tracking: "Bagaimana cara kerja ✓, penggantian, dan kalori di New Me?",
    faq_a_new_me_what: "New Me adalah program menu harian terpisah dengan dua rencana siap pakai – 1.300 atau 1.500 kalori – terdiri dari 2 makanan utama dan 2 camilan, dengan 3 pilihan untuk masing-masing. Sudah termasuk seluruh Premium. Harga: $11.99 per bulan (batalkan kapan saja) atau $99.99 sekali bayar, seumur hidup. Buka dari 💎 New Me di menu. Sebelum mulai ada kuesioner singkat yang diawali penafian medis yang perlu disetujui. Program ini hanya informasi umum dan tidak menggantikan dokter atau ahli gizi klinis.",
    faq_q_new_me_what: "Apa itu New Me dan bagaimana cara mendapatkannya?",
