    daily_focus_c1_d0: "Menjaga ruang tenangku dari hiruk pikuk di sekitarku", daily_focus_c1_d1: "Menetapkan batasan yang jelas, dengan penuh kasih dan tanpa rasa bersalah", daily_focus_c1_d2: "Tetap tenang meski ada badai di sekitarku", daily_focus_c1_d3: "Menjadikan ketenangan dan energiku sebagai prioritas utama", daily_focus_c1_d4: "Tidak ikut memikul perasaan dan suasana hati orang lain", daily_focus_c1_d5: "Tidak membiarkan kata-kata orang lain menggoyahkan nilai diriku",
