    daily_focus_p2_d4_s1: "Menjaga ritme kerja yang tepat agar membangun energi tinggi", daily_focus_p2_d4_s2: "Mengambil jeda dengan sengaja untuk mempertajam fokusku", daily_focus_p2_d4_s3: "Mempercayai rencana kerjaku dan tetap berpegang padanya", daily_focus_p2_d4_s4: "Memecah tugas besar menjadi langkah-langkah sederhana dan teratur", daily_focus_p2_d4_s5: "Mengenali kemajuan indah yang kucapai dalam beberapa hari terakhir",
