    faq_q_daily_focus_prompt: "Apa pengingat kecil yang menanyakan hal terpenting yang harus saya lakukan hari ini?", faq_a_daily_focus_prompt: "Ini pengingat harian Premium: sekali sehari lencana kecil “1” muncul di ikon asisten AI. Ketuk lencana itu untuk membuka gelembung yang menanyakan apa yang paling penting untuk Anda lakukan hari ini, langsung dengan 5 saran siap pakai (berganti setiap hari, bergilir melalui tema-tema berbeda sepanjang tahun agar selalu segar) ditambah 'Lainnya' untuk menulis sendiri - Anda bisa memilih lebih dari satu. Ketuk Tambah, dan pilihan Anda muncul sebagai label pengingat kecil di bagian atas 'Hariku' (bukan tugas untuk dicentang). Jika Anda menutupnya dengan ✕ atau mengetuk di luarnya, lencana hanya memudar untuk sisa hari itu alih-alih menghilang. Fitur ini aktif secara default, tetapi Anda bisa mematikannya di Pengaturan > Personalisasi & Kalender. Hari ini kurang pas? Ketuk '🌙 Jangan hari ini' – lencananya hilang sampai besok, lalu pertanyaannya kembali seperti biasa. Salah satu saran berasal dari kehidupan Anda sendiri – langkah berikutnya dari target bulan ini atau bacaan hari ini. Setiap hari adalah awal yang baru.",
